-- Creature say, yell and emote lines of the pandaria region: map 870 (Pandaria), from the world DB of
-- alexkulya/pandaria_5.4.8 release 2026_08_16, for creatures the world DB has no line for.
-- Generated by a port script (--region pandaria) from an export of
-- the world DB taken before this file was applied. A creature is in the region holding most of its 5.4.8
-- spawns (no spawn is unspawned). Rerunnable: this file's rows are replaced, entries with lines in the world DB are skipped.
-- German text is not in this file.
-- 180 entries, 491 rows.
-- 2 entries 5.4.8 gives lines are left alone: the world DB has lines for them: 63420,72057
-- 62 rows take text_female as text (text empty); 1 rows lose a different female line; 45 rows lose text_range

DROP TEMPORARY TABLE IF EXISTS `tmp_548_creature_text`;
CREATE TEMPORARY TABLE `tmp_548_creature_text` LIKE `creature_text`;
DELETE t FROM `creature_text` t JOIN `tmp_548_creature_text` n ON n.`entry` = t.`entry` AND n.`groupid` = t.`groupid` AND n.`id` = t.`id` AND n.`text` = t.`text`;
DROP TEMPORARY TABLE `tmp_548_creature_text`;
