INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(50332,0,0,'I am seeing red!',12,0,100,0,0,0,''),
(50333,0,0,'You have woken the bull, now face the horns!',12,0,100,0,0,0,''),
(50336,0,0,'You! What are you doing here?',12,0,100,0,0,0,''),
(50341,0,0,'Feel the fist of darkness!',12,0,100,0,0,0,''),
(50344,0,0,'Your end is near.',12,0,100,0,0,0,''),
(50347,0,0,'The darkness comes.',12,0,100,0,0,0,''),
(50363,0,0,'No! I must report back to Her!',12,0,100,0,0,0,''),
(50364,0,0,'Far from home, aren\'t you?',12,0,100,0,0,0,''),
(50750,0,0,'The pool stirs...',12,0,100,0,0,0,''),
(50768,0,0,'You disrupt my meditations? You will pay...',12,0,100,0,0,0,''),
(50780,0,0,'The thundering depths call to you...',12,0,100,0,0,0,'Sahn Tidehunter'),
(50782,0,0,'You die!',12,0,100,0,0,0,''),
(50783,0,0,'Stab stab stab stab stab!',12,0,100,0,0,0,''),
(50791,0,0,'I will wear your skin as a hat!',12,0,100,0,0,0,''),
(50805,0,0,'No! My gold!!',12,0,100,0,0,0,''),
(50811,0,0,'This darkness in my heart, it is your doing!',12,0,100,0,0,0,''),
(50816,0,0,'My vision is clouded, why have you done this to us?',12,0,100,0,0,0,''),
(50820,0,0,'I must give in to the anger! It is the only way!',12,0,100,0,0,0,''),
(50822,0,0,'The darkness in my soul screams for release!',12,0,100,0,0,0,''),
(50830,0,0,'Gimme dem munchins!!',12,0,100,0,0,0,''),
(50831,0,0,'Gonna hit you in the wikket!',12,0,100,0,0,0,''),
(50832,0,0,'You has ook for brains!',12,0,100,0,0,0,''),
(51078,0,0,'Gonna bash you into pretty flower food!',12,0,100,0,0,0,''),
(54763,0,0,'I don\'t know who you are, but you have my gratitude.',12,0,100,0,0,0,'Raufen - Nectarbreeze Farmer Rescue talk'),
(54763,0,1,'I never thought something like this could happen here...',12,0,100,0,0,0,'Raufen - Nectarbreeze Farmer Rescue talk'),
(54763,0,2,'I thought I was done for!',12,0,100,0,0,0,'Raufen - Nectarbreeze Farmer Rescue talk'),
(54763,0,3,'You don\'t have to tell me twice!',12,0,100,0,0,0,'Raufen - Nectarbreeze Farmer Rescue talk'),
(54915,0,0,'$n, you have no idea how glad I am to see you. Supervising is hungry work.',12,0,100,0,0,0,''),
(54917,0,0,'Join the students in the block formation below. Then follow the leader, as they do.',12,0,100,0,0,0,'Instructor Xann'),
(54918,0,0,'Enter the Rumpus Pit, then set off the firework. Be prepared to fight several enemies at once! Anything can happen in the Rumpus.',12,0,100,22,0,0,''),
(54918,1,0,'Now entering the arena: $n!',14,0,100,22,0,0,''),
(54918,2,0,'And now... let the Rumpus start!',14,0,100,22,0,0,''),
(54918,3,0,'Halfway there, $n. Keep it up!',14,0,100,22,0,0,''),
(54918,4,0,'You\'re nearly done, $n!',14,0,100,22,0,0,''),
(54918,5,0,'Congratulations to $n, victor of the Rumpus!',14,0,100,22,0,0,''),
(54925,0,0,'Very well!',14,0,100,0,0,0,''),
(54925,1,0,'I knew I would lose. The rivers told me so.',12,0,100,0,0,0,''),
(54926,0,0,'Fine, then. It\'s time for an open-faced $R sandwich!',14,0,100,0,0,0,''),
(54926,1,0,'You win... this time. I\'d better get back to my size training.',12,0,100,0,0,0,''),
(54960,0,0,'Stranger, have you ever seen a stone fall into a calm lake? Every action creates a ripple, even accepting a pledge of friendship. I shall think upon your request.',12,0,100,0,0,0,'Elder Lusshan to Player'),
(55009,0,0,'Over here, $n!',12,0,100,0,0,0,''),
(55092,0,0,'Did my son send you? There\'s plenty of stew to go around. Please, help yourself.',12,0,100,0,0,0,''),
(55196,0,0,'Your friend put up quite the fight. He nearly escaped, but now he is a prisoner, just like the rest of us.',12,0,100,0,0,30637,''),
(55201,0,0,'Are you friends with Admiral Taylor? If so, then I must test your strength in battle later.',12,0,100,0,0,0,''),
(55201,0,1,'The water spirits have answered my prayers. Thank you.',12,0,100,0,0,0,''),
(55201,0,2,'I had given up hope, friend. Thank you.',12,0,100,0,0,0,''),
(55201,0,3,'Do my eyes deceive me? Am I truly free?',12,0,100,0,0,0,''),
(55201,0,4,'I live another day, thanks to you.',12,0,100,0,0,0,''),
(55267,0,0,'I tried to boot a jade monster in the head but hurt my paw.',12,0,100,2,0,0,'Scared Pandaren Cub to Player'),
(55267,0,1,'Thank you for saving me!',12,0,100,2,0,0,'Scared Pandaren Cub to Player'),
(55267,0,2,'It was An! She dared Shin to go knock on the Jade Witch\'s door.',12,0,100,2,0,0,'Scared Pandaren Cub to Player'),
(55368,0,0,'You should join our family, preserved forever in jade.',12,0,100,1,0,0,'Widow Greenpaw to Player'),
(55490,0,0,'Are you part of the rescue team? Are we saved?',12,0,100,0,0,0,''),
(55490,0,1,'I knew someone would come for us. Thank you, $c!',12,0,100,0,0,0,''),
(55490,0,2,'Thank you, $c. I can get back to camp on my own.',12,0,100,0,0,0,''),
(55490,0,3,'They\'ve got the Admiral locked up like an animal. Please save him too.',12,0,100,0,0,0,''),
(55490,0,4,'The hozen revel in torturing their prisoners. Thank you, $c, for saving me from a dire fate.',12,0,100,0,0,0,''),
(55597,0,0,'Na Lek imbues $p with gratitude and returns to the waters of the pool.',16,0,100,0,0,0,''),
(55768,0,0,'Ah, a visitor! This is an incredible time for Pandaria - the mists have parted, and we rejoin the world. You come in peace, I hope?',12,0,100,0,0,30064,''),
(56114,0,0,'Yeah, I tried to hop through that thing too.',12,0,100,0,0,0,''),
(56114,0,1,'Once the trap is sprung no one gets in or out until the people trapped are completely drained of life. Mogu are evil.',12,0,100,0,0,0,''),
(56114,0,2,'Careful. Get stuck in that and it will drain your life to power itself.',12,0,100,0,0,0,''),
(56114,0,3,'I\'ve punched it, kicked it, smacked it, thwacked it. Nothing seems to break this oubliette.',12,0,100,0,0,0,''),
(56133,0,0,'Very well, $n. I will need your help making this beer.',12,0,100,0,0,0,''),
(56133,1,0,'When I yell out the names of ingredients, you throw them in the pot...',12,0,100,0,0,0,''),
(56133,2,0,'I am kidding!',14,0,100,0,0,0,''),
(56133,3,0,'I am the best brewer across three continents! I think I can handle this part.',12,0,100,0,0,0,''),
(56133,4,0,'If you wouldn\'t mind waiting, $n... this might take a long time.',12,0,100,0,0,0,''),
(56485,0,0,'I am sorry, but I cannot go back just yet.',12,0,100,0,0,27573,''),
(56485,1,0,'I\'ve decided to search for the Vale. I must find the Sacred Pools and study their healing powers.',12,0,100,0,0,27574,''),
(56485,2,0,'I\'m sorry, but I won\'t. I\'m sure you understand my reasons.',12,0,100,0,0,27575,''),
(56485,3,0,'Come on, let\'s go.',12,0,100,0,0,27576,''),
(56723,0,0,'Where are we? We were... swarming?!',12,0,100,0,0,0,''),
(56723,0,1,'What is happening? Why do we swarm so soon?',12,0,100,0,0,0,''),
(56779,0,0,'Ah, the dragon child and the hero. Together you will achieve great things.',12,0,100,2,0,37364,''),
(56779,1,0,'Tell me, dragon child: What is the nature of wisdom?',12,0,100,2,0,37365,''),
(56779,2,0,'Spoken like a true child of the Aspects. Always seeking to change the world.',12,0,100,2,0,37366,''),
(56779,3,0,'But true wisdom comes from KNOWING what is right. And sometimes, DOING nothing at all.',12,0,100,2,0,37367,''),
(56779,4,0,'To learn THAT is to learn true wisdom.',12,0,100,2,0,37368,''),
(56779,5,0,'Come forward! I will give you my blessing.',12,0,100,2,0,37369,''),
(56779,6,0,'My challenge, if you accept it, will test your cunning and footwork even in the midst of life-threatening danger.',12,0,100,2,0,37524,''),
(56782,0,0,'Hey, stranger! Pssst! Come over here!',12,0,100,0,0,0,'Rain-Zhu to Player'),
(56838,0,0,'Report?! I have my hands full down here, $n! Oh alright, here you go.',12,0,100,396,0,0,'Shokia'),
(56840,0,0,'Nazgrim gonna be real happy with Riko! Here! Report is done!',12,0,100,396,0,0,'Riko'),
(56841,0,0,'Here\'s the report, $n. Oh! Make sure you mention my idea with the bombs. I have it lined out in the report.',12,0,100,397,0,0,'Shademaster Kiryn'),
(57120,0,0,'Oh, I don\'t know. I am old, and I have always...',12,0,100,0,0,0,''),
(57120,1,0,'Look out! Mantid!',14,0,100,0,0,0,''),
(57120,2,0,'I\'ve reconsidered... it\'s too dangerous to stay here. No piece of land is worth losing your life over. Let me see those evacuation orders.',12,0,100,0,0,0,''),
(57121,0,0,'That\'s right. Now please, $r, leave and let us defend our property.',12,0,100,0,0,0,''),
(57122,0,0,'Pshh... outsiders. You know nothing about the Stoneplow way.',12,0,100,0,0,0,''),
(57122,1,0,'We\'re proud. We\'re strong. We are descended from the blood of the Tiller himself... and we don\'t run from trouble.',12,0,100,0,0,0,''),
(57162,0,0,'Oh, honey...',12,0,100,0,0,0,''),
(57163,0,0,'Daddy, is this nice person going to kill all the bad mantid soldiers?',12,0,100,0,0,0,''),
(57298,0,0,'A radish for sweet little Ella? Well, I sure can spare one. Here you go.',12,0,100,0,0,0,''),
(57319,0,0,'I keep hearing voices in my head. Should I be worried?',15,0,100,0,0,0,'Emulates player'),
(57319,0,1,'Why do I try so hard? It\'s all meaningless in the end...',15,0,100,0,0,0,'Emulates player'),
(57319,0,2,'Does this armor look a little tight on me?',15,0,100,0,0,0,'Emulates player'),
(57319,0,3,'Everyone around me only pretends to like me.',15,0,100,0,0,0,'Emulates player'),
(57319,0,4,'Nothing is ever going to change.',15,0,100,0,0,0,'Emulates player'),
(57319,0,5,'Of course my worst fears are going to come true.',15,0,100,0,0,0,'Emulates player'),
(57319,0,6,'What are people saying about me?',15,0,100,0,0,0,'Emulates player'),
(57319,0,7,'Why do I always feel so alone? Is it because...I\'m alone?',15,0,100,0,0,0,'Emulates player'),
(57385,0,0,'Would that I could, $c, but I have a bit of a weed problem. Say... you wouldn\'t be willing to help out, would you?',12,0,100,0,0,0,''),
(57402,0,0,'Little Ella\'s trying her hand at brewing? Well, I\'ll be! I wish her luck. Brewing isn\'t something a novice can just take up, you know. Anyhow, I can spare a Lakemelon for her.',12,0,100,0,0,0,''),
(58420,0,0,'Your serpent will arrive in just a moment. Good luck!',12,0,100,0,0,0,''),
(58506,0,0,'All right, ladies! Watch this!',14,0,100,0,0,0,''),
(58506,1,0,'Impressive! I\'m going to have to watch out for you.',12,0,100,0,0,0,''),
(58508,0,0,'Let\'s both do our best!',14,0,100,0,0,0,''),
(58508,1,0,'I lost again! I\'d better keep training.',12,0,100,0,0,0,''),
(58510,0,0,'I feel a rush of energy coming on. Let\'s do this!',14,0,100,0,0,0,''),
(58510,1,0,'Darnit, I lost! Oof... I feel tired...',12,0,100,0,0,0,''),
(58511,0,0,'Let us begin. Good luck.',14,0,100,0,0,0,''),
(58511,1,0,'You have bested me fairly. Well done.',12,0,100,0,0,0,''),
(58547,0,0,'Stay close and keep your eyes peeled.',12,0,100,0,0,0,''),
(58547,1,0,'The camp is just ahead, we should be able to make it from here.',12,0,100,0,0,0,''),
(58608,0,0,'I will never forget this, hero.',12,0,100,4,0,0,''),
(58608,0,1,'Thank you so much $p!',12,0,100,4,0,0,''),
(58608,0,2,'Thank you! They were saying we were going to be slaves.',12,0,100,4,0,0,''),
(58608,0,3,'They said they were looking for slaves and weapons.',12,0,100,4,0,0,''),
(58639,0,0,'I will never forget this, hero.',12,0,100,4,0,0,''),
(58639,0,1,'Thank you so much $p!',12,0,100,4,0,0,''),
(58639,0,2,'Thank you! They were saying we were going to be slaves.',12,0,100,4,0,0,''),
(58639,0,3,'They said they were looking for slaves and weapons.',12,0,100,4,0,0,''),
(58646,0,0,'Mmm, that\'s mighty tasty, $n. I wouldn\'t mind another round of that... or two... hic!',12,0,100,0,0,0,''),
(58704,0,0,'Speak to me when you are ready to try again.',12,0,100,0,0,0,'Kelari Featherfoot'),
(58705,0,0,'Awww shucks, I was gonna eat these! Well, if Ella needs \'em, I ain\'t gonna no more. Here, take \'em!',12,0,100,0,0,0,''),
(58706,0,1,'I was going to charge you a pretty penny for that peach, but Ella is such a good customer at my market, this one\'s on the house. Just this once, ya hear!',12,0,100,0,0,0,''),
(58710,0,0,'Wow! Thish ish shome amazing shtuff! Where can I get shome more?',12,0,100,0,0,0,''),
(58712,0,0,'Sure thing, $n! Enjoy!',12,0,100,0,0,0,''),
(58717,0,0,'Any time, neighbor. Any time.',12,0,100,0,0,0,''),
(58717,1,0,'Hmmm, this is excellent! EXCELLENT! This is the best stuff I\'ve tasted in a long time. Who brewed it?',12,0,100,0,0,0,''),
(58718,0,0,'First packet of seeds is on the house! Come back to me anytime you want to buy more seeds, ya hear?',12,0,100,0,0,0,''),
(58735,0,0,'Father! Are you okay?',12,0,100,0,0,0,''),
(58745,0,0,'And now for the moment of truth.',12,0,100,0,0,0,''),
(58745,1,0,'Aaaaaaaaahhh!',14,0,100,0,0,0,''),
(58745,2,0,'That... hurt...',12,0,100,0,0,0,''),
(58918,0,0,'You found...',41,0,100,0,0,0,''),
(58918,1,0,'A Lost Hen! Bring her back to a chicken coop.',41,0,100,0,0,0,''),
(58918,2,0,'A Wild Prairie Chicken! Kick him out of here!',41,0,100,0,0,0,''),
(58918,3,0,'A Marmot Disguised in Chicken Feathers! Expose him for the sham he really is!',41,0,100,0,0,0,''),
(58918,4,0,'An Amorous Rooster! Dip him in the water to cool his passions.',41,0,100,0,0,0,''),
(58918,5,0,'Old Hillpaw\'s prize-winning chicken, Mother Clucks!',41,0,100,0,0,0,''),
(58918,5,1,'Old Hillpaw\'s prize-winning chicken, Madam Specklybottom!',41,0,100,0,0,0,''),
(58918,5,2,'Old Hillpaw\'s prize-winning chicken, Thunderpeck!',41,0,100,0,0,0,''),
(58918,5,3,'Old Hillpaw\'s prize-winning chicken, Mantidsbane!',41,0,100,0,0,0,''),
(58918,5,4,'Old Hillpaw\'s prize-winning chicken, Rumblefeather!',41,0,100,0,0,0,''),
(58918,5,5,'Old Hillpaw\'s prize-winning chicken, Egga!',41,0,100,0,0,0,''),
(58918,5,6,'Old Hillpaw\'s prize-winning chicken, Stumbleflutter!',41,0,100,0,0,0,''),
(58918,5,7,'Old Hillpaw\'s prize-winning chicken, Buck-Bucka Betty!',41,0,100,0,0,0,''),
(58930,0,0,'I was barely inside their outer patrols when they caught me. I didn\'t find anything.',12,0,100,1,0,0,''),
(58930,1,0,'I saw their leader. He was heading further up the wall. I\'ll mark it on your map.',12,0,100,1,0,0,''),
(58930,2,0,'Thank you, friend. I didn\'t uncover anything before they caught me.',12,0,100,1,0,0,''),
(58930,3,0,'I... I failed. Thank you for coming for me.',12,0,100,1,0,0,''),
(58955,0,0,'The mogu ambushed us while we were trying to retreat from the mantid.',12,0,100,0,0,0,''),
(58955,0,1,'I must get to Stoneplow! The mantid will attack soon.',12,0,100,0,0,0,''),
(58955,0,2,'Thank you, hero.',12,0,100,0,0,0,''),
(58955,0,3,'Thank you, stranger.',12,0,100,0,0,0,''),
(59143,0,0,'I am in your debt.',12,0,100,2,0,0,''),
(59143,0,1,'I must rejoin the battle to save Binan Village.',12,0,100,2,0,0,''),
(59143,0,2,'Shaohao must have sent you.',12,0,100,2,0,0,''),
(59143,0,3,'We must drive the yaungol back to the Townlong Steppes.',12,0,100,2,0,0,''),
(59143,0,4,'You have great honor, stranger. Please join us.',12,0,100,2,0,0,''),
(59143,0,5,'Thank you. You have saved my life.',12,0,100,2,0,0,''),
(59143,0,6,'Join us, $c. We could use you in the fight.',12,0,100,2,0,0,''),
(59143,0,7,'That is powerful healing!',12,0,100,0,0,0,''),
(59305,0,0,'Report\'s all ready to go, $n! I don\'t mean to brag, but General Nazgrim should be pretty pleased with my work.',12,0,100,396,0,0,'Rivett Clutchpop'),
(59483,0,0,'Fool! I will crush you!',14,0,100,0,0,0,''),
(59483,7,0,'You have been affected by |cFFFF0404|Hspell:116784|h[Wildfire Spark]|h|r !',41,0,100,0,0,0,''),
(59483,8,0,'%s begins to channel a violent |cFFFF0404|Hspell:116040|h[Epicenter]|h|r!',41,0,100,0,0,0,''),
(59483,9,0,'%s begins to |cFFFF0404|Hspell:116711|h[Draw Flame]|h|r to his weapon!',41,0,100,0,0,0,''),
(59505,0,0,'This footprint is too muddy to be useful.',41,0,100,0,0,0,''),
(59505,0,1,'Next to this track, you see some bits of chewed up carrot.',41,0,100,0,0,0,''),
(59505,0,2,'The muddy track clearly shows a dexterous paw.',41,0,100,0,0,0,''),
(59505,0,3,'Stamped into the footprint is a clod of mud mixed with hay and yak hair.',41,0,100,0,0,0,''),
(59505,0,4,'Behind the print is the long impression of a prehensile tail.',41,0,100,0,0,0,''),
(59505,0,5,'Next to signs of a scuffle is a sharp, pointy spearhead and some colorful feathers.',41,0,100,0,0,0,''),
(60012,0,0,'Maybe I call myself $psfoot from now on.',12,0,100,0,0,0,''),
(60012,0,1,'Many thanks for rescue!',12,0,100,0,0,0,''),
(60293,0,0,'This raft is all yours, neighbor. You ever want to go rafting, just come back here. It\'ll be waiting for you.',12,0,100,25,0,0,'Max Narstave'),
(60491,0,0,'My fury is UNLEASHED!',14,0,100,0,0,29011,'Sha of anger 1'),
(60491,1,0,'Feed me with your ANGER!',14,0,100,0,0,29010,'Sha of anger 2'),
(60491,2,0,'Feel your rage!',14,0,100,0,0,29003,'Sha of anger 3'),
(60491,3,0,'Give in to your anger!',14,0,100,0,0,29005,'Sha of anger 4'),
(60491,4,0,'Extinguished!',14,0,100,0,0,29001,'sha of anger 5'),
(60491,5,0,'Yes, YES! Bring your rage to bear! Try to strike me down!',14,0,100,0,0,28999,'sha of anger 6'),
(61055,0,0,'Your pitiful rituals are meaningless! I will not be saved!',14,0,100,0,0,31309,''),
(61055,1,0,'Has Ban sent you to kill me, then? Just like he killed my husband?',12,0,100,0,0,31308,''),
(61055,2,0,'I see now... my hatred... consumed me. Tell Ban... all is... forgiven.',12,0,100,0,0,31311,''),
(61315,0,0,'The binding should only take a moment, but I\'ll be completely entranced.',12,0,100,0,0,0,''),
(61315,1,0,'Watch my back - I trust you can handle any interruptions.',12,0,100,0,0,0,''),
(61315,2,0,'All done. Did I miss anything?',12,0,100,0,0,0,''),
(61492,0,0,'Thank you, friend. Don\'t worry, it was just a scratch. Now I feel good as new!',12,0,100,0,0,0,''),
(61492,0,1,'I thought I was a goner. I owe you my life.',12,0,100,0,0,0,''),
(61492,0,2,'Thanks for saving me. It was rough up there.',12,0,100,0,0,0,''),
(61492,0,3,'I\'m alive? Ha! That\'s more than I can say for those Horde at Garrosh\'ar Point. We tore them up good.',12,0,100,0,0,0,''),
(61492,0,4,'Thank you. Time to lick my wounds and get back to the fight!',12,0,100,0,0,0,''),
(62202,0,0,'<cough> <hack> I have... returned.',12,0,100,0,0,30299,''),
(62220,0,0,'Demand?! You DEMAND?!',14,0,100,0,0,0,''),
(62220,1,0,'Who are YOU to make demands of the SHADO-PAN?',14,0,100,0,0,0,''),
(62377,0,0,'Nothing is free, $r. You want hops, you need to work.',12,0,100,0,0,0,''),
(62377,1,0,'Good enough! Now go water my Giant Carrots!',42,0,100,0,0,0,''),
(62377,2,0,'Keep going! Water my Cabbages!',42,0,100,0,0,0,''),
(62377,3,0,'Don\'t stop moving! Water those Sugar Beets!',42,0,100,0,0,0,''),
(62377,4,0,'Go water my Huge Melons, further down the path!',42,0,100,0,0,0,''),
(62377,5,0,'Keep it up! Now water my Red-Leaf Lettuce!',42,0,100,0,0,0,''),
(62377,6,0,'Looks like my Sugar Beets still need more water! Turn back!',42,0,100,0,0,0,''),
(62377,7,0,'Stop!',42,0,100,0,0,0,''),
(62377,8,0,'$ R, you needt to pay for everything . If you need a hop - will have to work .',12,0,100,1,0,0,'Smart text'),
(62385,0,0,'You\'ll have to ask Mung-Mung about that. He maintains our foodstores.',12,0,100,0,0,0,''),
(63013,0,0,'I will give you a free meal if you can get this dwarf off of my new chair!',12,0,100,1,0,0,''),
(63179,0,0,'This amber is ours, trespasser! Amber not for the mantid!',12,0,100,0,0,0,''),
(63217,0,0,'This stone tells of a great hozen warlord who lived here twenty-five hundred years ago. What are your leaders like? Poets? Warriors? I should like to meet them someday.',12,0,100,6,0,30072,''),
(63217,1,0,'Prepare yourself! Saurok raiders approach!',12,0,100,430,0,30073,''),
(63217,2,0,'The saurok have plagued this land since the time of the mogu. They are impossible to negotiate with. But we never stop trying! We fight them only as a last resort.',12,0,100,396,0,30074,''),
(63217,3,0,'Thank you for your help - these notes are important to my studies. Your people value knowledge too, yes? I assume so, only because you arrived on a great airship.',12,0,100,396,0,30075,''),
(63307,0,0,'I have everything I need. Quickly, let\'s move on before they return!',12,0,100,396,0,30076,''),
(63307,1,0,'Enough about pandaren history. Let\'s talk about your people, traveler.',12,0,100,396,0,31772,''),
(63307,2,0,'I\'ve learned a great deal already just by watching you in action. You fight with the fervor of youth but the experience of an old veteran. You\'ve seen a lifetime of warfare, haven\'t you?',12,0,100,396,0,31773,''),
(63307,3,0,'Ah, this is a special place. My great grandparents called this part of the forest their home. Come, this will take only a moment.',12,0,100,396,0,31774,''),
(63307,4,0,'We Pandaren do not worship our ancestors, but we revere their memory and the wisdom that they have passed on to us.',12,0,100,396,0,31776,''),
(63307,5,0,'It was my Great Grandfather who first told me the tale of the mogu that I recently shared with you.',12,0,100,396,0,31775,''),
(63315,0,0,'Welcome to our first officially-sanctioned combat event, the Arena of Annihilation!',14,0,100,0,0,0,''),
(63315,1,0,'Are you ready to display your martial prowess here, in the eye of The Tiger?',14,0,100,0,0,0,''),
(63315,2,0,'Then HIT THAT GONG, and show these monks what you\'re made of! ...one way or another, heh.',14,0,100,0,0,0,''),
(63315,3,0,'For our first show of skill and power we bring you SCAR-SHELL, mightiest of dragon turtles!',14,0,100,0,0,0,''),
(63315,4,0,'Whew, what a mess! Someone inform the monastery kitchens: We\'re having turtle soup, tonight!',14,0,100,0,0,0,''),
(63315,5,0,'Ready for the next fight? Ring that gong and GET! IT! ON!',14,0,100,0,0,0,''),
(63315,6,0,'It\'s time for the grummle-grubbing goliath, fifteen feet of furry fury, Kun-Lai Summit\'s own snow-stalking horror, JOL\'GRUM!',14,0,100,0,0,0,''),
(63315,7,0,'OUCH! Safe to say that Jol\'Grum wasn\'t quite yet-i ready for his battle with these three killing machines! Speaking of ready...',14,0,100,0,0,0,''),
(63315,8,0,'She\'s here to make new friends... and then set them on fire! It\'s Pandaria\'s prettiest little playful pyromaniac, Liuyang!',14,0,100,0,0,0,''),
(63315,9,0,'Snuffed out like a candle! Is there anyone these three can\'t beat?!',14,0,100,0,0,0,''),
(63315,10,0,'Did someone say Yak Attack?! It\'s ax-master Chagan Firehoof, wandering warrior of the Townlong Steppes!',14,0,100,0,0,0,''),
(63315,11,0,'What a battle! Our fine combatants served up Chagan a heaping helping of Yaungolian barbeque...',14,0,100,0,0,0,''),
(63315,12,0,'Flitting through the mists with death upon his fists comes the sinister and serene jinyu assassin: Satay Byu!',14,0,100,0,0,0,''),
(63315,13,0,'Ooo, that\'s one killer carp whose slaying days have come to a fishy end.',14,0,100,0,0,0,''),
(63315,14,0,'Everyone, please cheer for the NEW CHAMPIONS of the Arena of Annihilation!',14,0,100,0,0,0,''),
(63535,0,0,'Someone has come to save us? Perhaps all is not lost...',12,0,100,1,0,0,''),
(63542,0,0,'Someone has come to save us? Perhaps all is not lost...',12,0,100,1,0,0,''),
(63751,0,0,'I don\'t know about this "Horde", but you look trustworthy. I\'ll gather everyone up and meet you when we\'re ready to rebuild!',12,0,100,1,0,0,''),
(63754,0,0,'I don\'t know about this "Alliance", but you look trustworthy. I\'ll gather everyone up and meet you when we\'re ready to rebuild!',12,0,100,1,0,0,''),
(63955,0,0,'%s swims excitedly through the vents of warm water.',16,0,100,0,0,0,''),
(63955,1,0,'%s rubs against the prow of the Mist-Hopper and whimpers.',16,0,100,0,0,0,''),
(63955,2,0,'%s looks around cautiously before leaving his mark on the whale corpse.',16,0,100,0,0,0,''),
(64071,0,0,'Please, partake in the buffet laid out by the Golden Lotus as a thanks to your people for their aid in protecting the Vale of Eternal Blossoms.',12,0,100,1,0,0,''),
(64072,0,0,'How\'s about another round?',12,0,100,1,0,0,''),
(64072,0,1,'Well played, sir.',12,0,100,1,0,0,''),
(64115,0,0,'Hrmph. Nice card.',12,0,100,1,0,0,''),
(64115,0,1,'Alright, alright, you win.',12,0,100,1,0,0,''),
(64115,0,2,'Best two out of three!',12,0,100,1,0,0,''),
(64149,0,0,'I have the softest featherbeds you can find for a thousand miles. Would you like to try one?',12,0,100,1,0,0,''),
(64164,0,0,'Fear not if your weapon leaves your grasp. Your body is an ample tool against any foe.',12,0,100,1,0,0,''),
(64312,0,0,'Hmmm, I reckon I don\'t know, $r. All I can understand is the part about the valley - that\'s right here! The Valley of the Four Winds!',12,0,100,0,0,0,''),
(64313,0,0,'The maiden, eh? Hmm, I remember that\'s what my father used to call that river to the north. Other than that, I wouldn\'t have the slightest clue.',12,0,100,0,0,0,''),
(64315,0,0,'Oh, I HAVE heard of the ancestors\' stair. That\'s what some folks call those mountains to the north.',12,0,100,0,0,0,''),
(64327,0,0,'What echoes and what\'s dark? It\'s simple! A cave!',12,0,100,0,0,0,''),
(64528,0,0,'Ah, another stranger from beyond the mists.',12,0,100,396,0,29030,''),
(64528,1,0,'Ten thousand years ago, the last Pandaren Emperor came seeking my advice. He, too, was filled with conflict. Let us see if you are correct, Taran. Let us see how this stranger deals with turmoil of the soul.',12,0,100,396,0,29031,''),
(64528,2,0,'We can agree it is noble to fight for a righteous cause: to defend home or family. But what of vengeance? What of anger? I sense these emotions run deep in this one.',12,0,100,396,0,29033,''),
(64528,3,0,'Well spoken, Zhi. The strangers from beyond the mists have no shortage of passions, but let us see if they indeed control them. Beyond anger lies hatred, the wellspring of all misery. What is this? Your hatred has a face!',12,0,100,396,0,29035,''),
(64528,4,0,'This one has indeed proven mastery over anger. Between the young cub\'s words and the actions of this hero, I think I understand. Those from beyond the mists are hardened by battle. They are scarred, yes, but they have learned much. I trust them.',12,0,100,396,0,29037,''),
(64536,0,0,'Soon they will overwhelm this continent! Where do we draw the line?',12,0,100,396,0,28417,''),
(64536,1,0,'We have witnessed your "help" in the Jade Forest. This "Horde," this "Alliance" of yours - you have no control over your own nature. You leave misery in your wake.',12,0,100,396,0,28418,''),
(64536,2,0,'Violence. See? They are filled with it.',12,0,100,396,0,28419,''),
(64536,3,0,'All you seek to conquer is each other!',12,0,100,396,0,28420,''),
(64536,4,0,'See? See how these outsiders hate one another! They wear their hatred to battle and carry it to their graves!',12,0,100,396,0,28421,''),
(64537,0,0,'It is true. They are strong. There is much they can teach us.',12,0,100,5,0,29050,''),
(64537,1,0,'To live without anger is not to live at all. It is ours to overcome. In defeating our anger, we draw great strength.',12,0,100,5,0,29051,''),
(64537,2,0,'How interesting. They bring much to our land, but they also bring the shadow of war.',12,0,100,5,0,29052,''),
(64540,0,0,'We\'re here to lend our aid. We can help you rebuild the Vale.',12,0,100,396,0,38017,''),
(64540,1,0,'Yes... we are fighters. But we come from a violent land. We fought off demons, we fought off death, we even fought against the very end of the world!',12,0,100,396,0,27589,''),
(64540,2,0,'Anger is a part of us all, yes. But we value control. The orcs were once driven solely by anger - they lived in a state of bloodlust - but they conquered it.',12,0,100,396,0,27590,''),
(64540,3,0,'That... that looks just like Garrosh Hellscream!',12,0,100,396,0,27592,''),
(64540,4,0,'No, that\'s not true - there is so much more to us than this!',12,0,100,396,0,27593,''),
(64540,5,0,'Peace will come. I swear it. And old hatreds will go away. You have to believe me.',12,0,100,396,0,27594,''),
(64597,0,0,'Mmmmm, I haven\'t tasted a brew of this complexity and clarity since... well... since the golden age of the Stormstout Brewery! Whoever made this has a real talent.',12,0,100,0,0,0,''),
(64822,0,0,'I often venture out here to think. The view is breathtaking, would you agree?',12,0,100,0,0,29124,'WRATHION_INTRO_VENTURE'),
(64822,1,0,'Pandaria is indeed a jewel. Such beauty. It makes you want to protect her, yes?',12,0,100,0,0,29125,'WRATHION_ABOUT_PANDARIA'),
(64822,2,0,'I feel the same way about Azeroth herself.',12,0,100,0,0,29126,'WRATHION_ABOUT_PROTECT_AZEROTH'),
(64822,3,0,'You have done great things, friend. I can assure you this is but the beginning of our work together.',12,0,100,0,0,29127,'WRATHION_GREAT_THINGS'),
(64822,4,0,'Behold: The power of the foes you\'ve vanquished.',12,0,100,0,0,29128,'WRATHION_POWER_OF_ENEMIES'),
(64822,5,0,'And the wisdom of those you\'ve outsmarted.',12,0,100,0,0,29129,'WRATHION_WISDOM_OF_ENEMIES'),
(64822,6,0,'Here! The embodiment of the fear that you\'ve conquered. May it now strike terror into the hearts of your enemies!',12,0,100,0,0,29130,'WRATHION_TERROR_OF_ENEMIES'),
(64822,7,0,'Finally, a gift from me. Make no mistake: the Black Dragonflight lives on!',12,0,100,0,0,29131,'WRATHION_BREATH_TO_GEM'),
(64822,8,0,'There. My work is done. You can now greatly augment the power of any sha-touched weapon.',12,0,100,0,0,29132,'WRATHION_WORK_IS_DONE'),
(64946,0,0,'Mmmmm. Mmmmmm...... This is... simply put... amazing. Your friend Ella has real talent! Tell her to speak to my Uncle Gao at the Brewery. I think she has found a new home with us Stormstouts.',12,0,100,0,0,0,''),
(65586,0,0,'Thank you. I owe you greatly.',12,0,100,0,0,0,'Restless Leng'),
(65586,1,0,'I overheard a great deal through the cage. Rensai will be pleased with what I have to tell him.',12,0,100,1,0,0,'Restless Leng'),
(65586,2,0,'I hope we meet again soon, my new friend.',12,0,100,1,0,0,'Restless Leng'),
(65910,0,0,'Just a moment, Teng. We have... a visitor.',12,0,100,0,0,0,'q31736 - Sunke Khang'),
