(66366,0,2,'I miss my family. I miss my home!',1,0,100,0,0,0,'q31744 - Captive Pandaren Cub'),
(66366,0,3,'I thought those eyes would NEVER leave me alone!',1,0,100,5,0,0,'q31744 - Captive Pandaren Cub'),
(66366,0,4,'I... I thought I\'d be here forever...',1,0,100,1,0,0,'q31744 - Captive Pandaren Cub'),
(66366,0,5,'Thanks! I don\'t like the Horde.',1,0,100,0,0,0,'q31744 - Captive Pandaren Cub'),
